function [Ra2014,Ri2014,cct,duv]=CRI2014(spd)
% Calculate CRI2014 v1.0 (IES paper, Optics Express 2015)
% Input:
%	spd = spectral power distribution of white light source 
% Output:
%	Ra2014: Ra2014 alculated using 99 sample set 
%	Ri2014: Ri2014 alculated using 99 sample set 
%	cct: correlated colour temperature of test light
%	duv: duv of test light


%use all hues
thetas=[0, 360];

[Ra2014,Ri2014]=CRI2014_sub(spd,7.54,thetas,99);

end

