%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function [DEi,DERMS,aMc, bMc,Jc,XYZT,T,dc,aMr,bMr,Jr]=DEi_cam02ucs(S1,sampleset,CCTtype,ref)

%set CAM02UCS parameters
Yb=20;F=1;Did=1;Nc=1;c=0.69;LA=100;
nm=(360:1:830)';
lambda=S1(:,1);

[XYZWT]=spd2xyz(S1,2,0);


%step 2: calculating colour temperature
[T,dc]=CCTa(XYZWT,2);

%Calculate reference spectrum
if nargin>=4 & size(ref,1)~=1;
    Sr=CIEinterp(ref(:,1),ref(:,2),lambda,'v5cubic');
    Sr=[lambda,Sr./(sum(Sr).*abs(lambda(1)-lambda(2)))];
    Sr(isnan(Sr))=0;
else %if nargin
    if nargin >=4; T=ref;end
    if CCTtype==-1;
        Sr=CCT2CIErefmix(T,lambda);
    else %else CCTtype
        if CCTtype==0;
            Sr=blackbodySPD(T,lambda);
        else
            Sr=daylightSPD(T,lambda);
        end
    end 
    %Sr=[lambda,CIEinterp(Sr(:,1),Sr(:,2),lambda,'v5cubic')];%use same range as input spectrum
    Sr(isnan(Sr))=0;
end

%use 10 degree for all other calculations
[XYZT,XYZWT]=spd2xyz(S1,10,0,sampleset);
[XYZR,XYZWR]=spd2xyz(Sr,10,0,sampleset);


for i=1:size(XYZT,3);
    XYZT_i=XYZT(:,:,i);
    XYZWT_i=XYZWT(i,:);
    XYZR_i=XYZR(:,:,i);
    XYZWR_i=XYZWR(i,:);

    %step 5
    [J,C,H,M,s,Q,h,Hc,D,A,td,InfSucFail]=CIECAM02ForwardM(XYZT_i,XYZWT_i,Yb,Did,F,Nc,c,LA);
    J=J';M=M';h=h';
    Jc(:,i)=(1+100*0.007)*J./(1+0.007*J);
    Mc=(1/0.0228)*log(1+0.0228*M);
    aMc(:,i)=Mc.*cos(h*pi/180);
    bMc(:,i)=Mc.*sin(h*pi/180);

    h_=h;
    %step 6
    [J,C,H,M,s,Q,h,Hc,D,A,td,InfSucFail]=CIECAM02ForwardM(XYZR_i,XYZWR_i,Yb,Did,F,Nc,c,LA);
    J=J';M=M';h=h';
    Jr(:,i)=(1+100*0.007)*J./(1+0.007*J);
    Mr=(1/0.0228)*log(1+0.0228*M);
    aMr(:,i)=Mr.*cos(h*pi/180);
    bMr(:,i)=Mr.*sin(h*pi/180);
    hmr=h;
    %step 7

    DEi(:,i)=((Jc(:,i)-Jr(:,i)).^2+(aMc(:,i)-aMr(:,i)).^2+(bMc(:,i)-bMr(:,i)).^2).^0.5;
    DERMS(i)=sqrt(sum(DEi(:,i).^2)./length(DEi(:,i)));
end
end
